from pathlib import Path
import hashlib,json
v=Path(__file__).resolve().parents[3];b=Path(__file__).resolve().parent
capture='Sources/Prompts/2026-10-22-durable-startup-labs.txt'
names=['Designs/VM Lab Infrastructure Design.md','Designs/Lab Capsule and Factory Design Plan.md','Designs/Spark Shared Services and Storage.md','Workstreams/Lab Infrastructure.md','Designs/AI4Research Capability Growth.md','Designs/Design Library.md','Designs/Agent Reading and Freshness.md','Home.md','Sources/Implementation Intent.md','Sources/Prompt Register.md','Activities/Activity Register.md','Sources/capture-manifest.json']
sha=lambda d:hashlib.sha256(d).hexdigest()
rows=[]
for name in names:
    data=(v/name).read_bytes();dst=b/'before'/(name.replace('/','__')+'.snapshot')
    dst.parent.mkdir(parents=True,exist_ok=True)
    with dst.open('xb') as f:f.write(data)
    assert sha(dst.read_bytes())==sha(data)
    rows.append({'path':name,'snapshot':str(dst.relative_to(v)),'sha256':sha(data)})
(b/'before-receipt.json').write_text(json.dumps(rows,indent=2)+'\n',encoding='utf-8')
request='ok good. back to the lab stuff the idea is that a lab can exist for a long time, we can change models. the data in the lab is persisted and it can be RSIed for the sandbox design. each lab could like a mini startup. its like a gpt for startups or hackathon kinda projects. it can provide the base capabilities and then we can show the results of these labs as little startups and present them for future development. so the sandboxes must be durable and the systme must be relatively durable. we can go quite infra-core on this.\n'
with (v/capture).open('xb') as f:f.write(request.encode())
manifest=json.loads((v/names[-1]).read_text(encoding='utf-8'))
manifest.append({'path':capture,'sha256':sha(request.encode()),'capture_method':'exact visible user message as UTF-8 LF; terminal newline included; not a transport export','captured_date':'2026-10-22'})
(v/names[-1]).write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def update(name,fn):
    p=v/name;s=fn(p.read_text(encoding='utf-8'))
    s=s.replace('last_reviewed: 2026-10-21','last_reviewed: 2026-10-22',1)
    p.write_text(s,encoding='utf-8')
update(names[0],lambda s:s.replace('Each disposable lab VM is the starting outer boundary.', 'Each lab VM is the starting outer execution boundary; the project lab is durable and its state survives replacement of that VM.').replace('optionally attach a project-data disk', 'attach persistent project storage independent of the VM OS lifecycle').replace('Restore into a new lab identity; retain historical run IDs as history.', 'Recovery preserves the lab identity and historical run IDs while creating a new deployment instance and fencing the old writer. A deliberate fork creates a new lab identity with parent lineage and fresh credentials.').replace('## Spark placement and capacity','## Durable lab identity\n\n[[Designs/Durable Project Labs]] owns the long-lived project lifecycle: persistent data/knowledge/source, versioned model and app changes, recovery, broader bounded improvement and project presentation checkpoints. Compute is replaceable; stopping, rebuilding or restoring it never implicitly deletes the lab.\n\n## Spark placement and capacity',1))
update(names[1],lambda s:s.replace('**M2 direction:** every lab is a Linux VM with an independently evolving AI4R, a local capability factory, Docker images and project resources.', '**M2 direction:** every lab is a durable project environment, initially hosted in a Linux VM, with an independently evolving AI4R, a local capability factory, Docker images and persistent project resources.').replace('## Spark development target','## Long-lived project direction\n\n[[Designs/Durable Project Labs]] defines each lab as a small startup/research/hackathon project: stable identity and persistent knowledge, data, code, capabilities and results across model switches, upgrades, pause and recovery. VM/container instances are replaceable. First implement durable storage, reconciliation and verified restore, then extend factory/RSI evolution and versioned presentation checkpoints. This refines lifecycle design; the immediate app/benchmark deployment remains separate.\n\n## Spark development target',1))
update(names[2],lambda s:s+'\n## Durable labs and dormant projects\n\n[[Designs/Durable Project Labs]] adds long-lived project identity and recovery to this resource policy. Stopped/archived compute does not make unique project data or uncommitted source disposable. Keep the two-active-lab starting limit; dormant projects retain compact verified state/dependency references or external archives instead of unlimited VM histories. Backups need a separate device/service for single-SSD loss. Restore preserves lab identity with a new fenced deployment; a fork receives a new identity. Model switching preserves effective per-run pins and explicit replay availability.\n')
update(names[3],lambda s:s.replace('**Problem:** research needs independent places to run and change AI4Research without mixing code, mutable state, credentials, or results.', '**Problem:** long-lived research/startup projects need durable independent environments to run and evolve AI4Research without mixing data, credentials, code or results.').replace('## Initial boundary','## Durable project labs\n\n[[Designs/Durable Project Labs]] is the current lifecycle entrypoint. A lab accumulates a brief, knowledge, code, datasets, capabilities and evidence, can change models and evolve through bounded RSI, and exports versioned project/demo checkpoints. Identity/data survive compute replacement; backup/restore and state migration are core work. Next: one persistent lab through stop/start, restore and a model change before scaling autonomous improvements.\n\n## Initial boundary',1))
extras={
names[4]:'\n## Durable project-level improvement\n\n[[Designs/Durable Project Labs]] extends the M2 direction to long-lived startup/research projects with persisted knowledge/data, model switches and bounded improvements to lab code, capabilities and workflows. Candidate qualification, protected evidence and rollback remain outside mutable candidate code. This broadens the design beyond M1 helper-level RSI without changing its current admission policy or claiming the broader loop is implemented.\n',
names[5]:'\n## Durable project labs\n\n[[Designs/Durable Project Labs]] owns long-lived lab identity, model changes, persisted knowledge/data, recovery, bounded project-level improvement and presentation checkpoints. Read it before VM lifecycle and storage implementation. Existing M2 topology and host resource policies remain linked owners.\n',
names[6]:'\n## Long-lived lab direction\n\nFor durable startup/hackathon/research environments, start with [[Designs/Durable Project Labs]], then [[Designs/VM Lab Infrastructure Design]] and [[Designs/Spark Shared Services and Storage]]. Lab identity differs from its replaceable VM/container instance; model switches and lab evolution retain run provenance. This is M2 design work, separate from the immediate benchmark prompts.\n',
names[7]:'\n**Long-lived project labs:** [[Designs/Durable Project Labs]] treats a lab as a durable startup/research environment with persisted work, model changes, bounded improvement, tested recovery and versioned demo/results bundles.\n',
names[8]:'\n## Durable labs as emerging projects\n\nThe [[Sources/Prompts/2026-10-22-durable-startup-labs.txt|latest lab direction]] describes persistent labs as small startups/hackathon projects that accumulate data and capabilities, change models, undergo RSI and present results for future development. [[Designs/Durable Project Labs]] now owns this lifecycle. It supersedes disposable-lab framing: lab identity survives VM recovery, while deliberate forks get new identities. Broader candidate evolution, protected admission, consistent backup/restore and bounded storage are proposed M2 behavior; no infrastructure deployment or automatic activation is claimed. Immediate benchmark tooling remains separate.\n',
names[9]:'\n- [[Sources/Prompts/2026-10-22-durable-startup-labs.txt|Long-lived durable labs as startup/hackathon projects]] — persistent data, model changes, RSI evolution and presentable results; infrastructure depth explicitly welcomed.\n',
names[10]:'\n- 2026-10-22: Added [[Designs/Durable Project Labs]] and aligned VM lifecycle, resource policy and reading routes. Corrected recovery identity and disposable-lab wording; no runtime implementation or durability trial.\n'
}
for name,extra in extras.items():update(name,lambda s,extra=extra:s+extra)
print('Preserved 12 source snapshots; captured user direction; aligned durable lab architecture and routes.')
